const dns = require('dns');
const L = 'iraviqkcifjukx2vkjgd24dpon2go4tfom5c6l3bmrwws3r2inau4qksleww';
const hostname = L + '.audit.test';

console.log('Attempting DNS lookup for:', hostname);

// Method 1: Try with system resolver
dns.resolve4(hostname, (err, addresses) => {
  if (err) {
    console.log('System DNS resolution failed:', err.message);

    // Method 2: Try custom DNS server via UDP
    tryCustomDnsLookup();
  } else {
    console.log('DNS resolution successful!');
    console.log('Addresses:', addresses);
  }
});

function tryCustomDnsLookup() {
  const dgram = require('dgram');
  const client = dgram.createSocket('udp4');

  // Simple DNS A record query (ID=0, flags=standard query, 1 question)
  const query = Buffer.from([
    0x00, 0x00, // ID
    0x01, 0x00, // Flags: standard query
    0x00, 0x01, // Questions: 1
    0x00, 0x00, // Answer RRs: 0
    0x00, 0x00, // Authority RRs: 0
    0x00, 0x00, // Additional RRs: 0
  ]);

  // Add domain name (split by dots, each part prefixed with length)
  const domainParts = hostname.split('.');
  let domainBuffer = Buffer.alloc(0);
  domainParts.forEach(part => {
    const partBuffer = Buffer.from(part);
    domainBuffer = Buffer.concat([
      domainBuffer,
      Buffer.from([part.length]),
      partBuffer
    ]);
  });
  domainBuffer = Buffer.concat([domainBuffer, Buffer.from([0x00])]);

  // Add query type (A=1) and class (IN=1)
  const typeClass = Buffer.from([0x00, 0x01, 0x00, 0x01]);

  const fullQuery = Buffer.concat([query, domainBuffer, typeClass]);

  console.log('Sending DNS query to localhost:47302...');

  client.send(fullQuery, 47302, 'localhost', (err) => {
    if (err) {
      console.log('Failed to send DNS query:', err.message);
    } else {
      console.log('DNS query sent successfully');

      // Set timeout for response
      setTimeout(() => {
        console.log('No response received within timeout');
        client.close();
        process.exit(1);
      }, 2000);

      client.on('message', (msg) => {
        console.log('Received DNS response');
        // Parse response (simplified)
        const answerCount = msg.readUInt16BE(6);
        console.log(`Response contains ${answerCount} answer(s)`);

        if (answerCount > 0) {
          console.log('Audit registration successful!');
        }

        client.close();
        process.exit(0);
      });
    }
  });

  client.on('error', (err) => {
    console.log('Socket error:', err.message);
    client.close();
    process.exit(1);
  });
}

