const dgram = require('dgram');

function dnsQuery(domain, server = 'localhost', port = 47302) {
    return new Promise((resolve, reject) => {
        // Create DNS query packet
        const transactionId = Buffer.from([0x12, 0x34]);
        const flags = Buffer.from([0x01, 0x00]); // Standard query, recursion desired
        const questions = Buffer.from([0x00, 0x01]); // 1 question
        const answerRrs = Buffer.from([0x00, 0x00]);
        const authorityRrs = Buffer.from([0x00, 0x00]);
        const additionalRrs = Buffer.from([0x00, 0x00]);

        // Encode domain name
        let dnsQuery = Buffer.alloc(0);
        const parts = domain.split('.');
        for (const part of parts) {
            dnsQuery = Buffer.concat([
                dnsQuery,
                Buffer.from([part.length]),
                Buffer.from(part)
            ]);
        }
        dnsQuery = Buffer.concat([dnsQuery, Buffer.from([0x00])]); // End of domain

        // Query type A (1) and class IN (1)
        dnsQuery = Buffer.concat([
            dnsQuery,
            Buffer.from([0x00, 0x01]), // Type A
            Buffer.from([0x00, 0x01])  // Class IN
        ]);

        // Construct full packet
        const packet = Buffer.concat([
            transactionId,
            flags,
            questions,
            answerRrs,
            authorityRrs,
            additionalRrs,
            dnsQuery
        ]);

        // Create socket
        const socket = dgram.createSocket('udp4');

        // Set timeout
        const timeout = setTimeout(() => {
            socket.close();
            reject(new Error('DNS query timeout'));
        }, 2000);

        socket.on('message', (msg) => {
            clearTimeout(timeout);
            socket.close();
            resolve(msg);
        });

        socket.on('error', (err) => {
            clearTimeout(timeout);
            socket.close();
            reject(err);
        });

        // Send query
        socket.send(packet, port, server, (err) => {
            if (err) {
                clearTimeout(timeout);
                socket.close();
                reject(err);
            }
        });
    });
}

