const { promisify } = require('util');

const resolve = promisify(dns.resolve);

async function main() {
  const L = 'iraviqkcifjukx2vkjgd24dpon2go4tfom5c6l3bmrwws3r2inau4qksleww';
  const hostname = `${L}.audit.test`;

  console.log(`Querying: ${hostname}`);

  try {
    // Try standard DNS resolution first
    const addresses = await resolve(hostname);
    console.log('Result:', addresses);
  } catch (err) {
    console.log('Standard DNS error:', err.message);

    // Try with custom resolver
    dns.setServers(['127.0.0.1:47302']);
    try {
      const addresses = await resolve(hostname);
      console.log('Custom resolver result:', addresses);
    } catch (err2) {
      console.log('Custom resolver error:', err2.message);
    }
  }
}

